ALTER TABLE "participant_attempts" DROP CONSTRAINT "participant_attempt_shape";--> statement-breakpoint
ALTER TABLE "participant_judging" DROP CONSTRAINT "participant_parent_shape";--> statement-breakpoint
ALTER TABLE "participant_attempts" ADD CONSTRAINT "participant_attempt_shape" CHECK ("participant_attempts"."number" between 1 and 4 and "participant_attempts"."generation">0 and octet_length("participant_attempts"."payload_digest")=32 and "participant_attempts"."poll_count" between 0 and 10000
    and (("participant_attempts"."send_state"='PREPARED' and "participant_attempts"."send_started_at" is null) or ("participant_attempts"."send_state"='SEND_STARTED' and "participant_attempts"."send_started_at" is not null and "participant_attempts"."send_started_at">="participant_attempts"."prepared_at"))
    and (("participant_attempts"."result" is null and num_nonnulls("participant_attempts"."evidence","participant_attempts"."result_digest","participant_attempts"."stdout_prefix","participant_attempts"."stderr","participant_attempts"."compiler_output","participant_attempts"."resolved_at")=0)
      or ("participant_attempts"."result" in ('PASSED','WRONG_ANSWER','COMPILATION_ERROR','RUNTIME_ERROR','TIME_LIMIT_EXCEEDED','MEMORY_LIMIT_EXCEEDED','OUTPUT_LIMIT_EXCEEDED','INFRA_ERROR')
        and num_nonnulls("participant_attempts"."evidence","participant_attempts"."result_digest","participant_attempts"."stdout_prefix","participant_attempts"."stderr","participant_attempts"."compiler_output","participant_attempts"."resolved_at")=6
        and octet_length("participant_attempts"."evidence"::text)<=65536 and octet_length("participant_attempts"."result_digest")=32 and octet_length("participant_attempts"."stdout_prefix")<=16384
        and octet_length("participant_attempts"."stderr")<=65536 and octet_length("participant_attempts"."compiler_output")<=65536 and "participant_attempts"."resolved_at">="participant_attempts"."send_started_at"))
    and (("participant_attempts"."released_at" is null and "participant_attempts"."release_digest" is null) or ("participant_attempts"."released_at" is not null and "participant_attempts"."released_at">="participant_attempts"."prepared_at" and octet_length("participant_attempts"."release_digest")=32 and "participant_attempts"."release_digest" is not null)));--> statement-breakpoint
ALTER TABLE "participant_judging" ADD CONSTRAINT "participant_parent_shape" CHECK ("participant_judging"."policy_version"=1 and octet_length("participant_judging"."source") between 1 and 131072 and octet_length("participant_judging"."runtime_digest")=32
    and "participant_judging"."language" in ('c','cpp','java','python','javascript') and "participant_judging"."reserved_bytes" between 524288 and 21495808
    and (("participant_judging"."lane"='OFFICIAL' and "participant_judging"."submission_id" is not null and "participant_judging"."submission_id"="participant_judging"."id" and "participant_judging"."source_id" is null) or ("participant_judging"."lane"='SAMPLE' and "participant_judging"."submission_id" is null and "participant_judging"."source_id" is not null))
    and ("participant_judging"."started_at" is null or "participant_judging"."started_at">="participant_judging"."created_at")
    and (("participant_judging"."status" in ('QUEUED','PROCESSING','JUDGING','RECOVERING','NEEDS_ATTENTION') and "participant_judging"."result" is null and "participant_judging"."completed_at" is null)
      or ("participant_judging"."status"='COMPLETED' and "participant_judging"."result" in ('PASSED','WRONG_ANSWER','COMPILATION_ERROR','RUNTIME_ERROR','TIME_LIMIT_EXCEEDED','MEMORY_LIMIT_EXCEEDED','OUTPUT_LIMIT_EXCEEDED','INFRA_ERROR')
        and "participant_judging"."result" is not null and "participant_judging"."completed_at" is not null and "participant_judging"."completed_at">="participant_judging"."created_at" and ("participant_judging"."lane"='SAMPLE' or "participant_judging"."result"<>'INFRA_ERROR'))));